<?php
/**
 * QPOS Product List horizontal scroll installer.
 * Upload this file beside public/index.php, run it once with the required key,
 * then delete it immediately.
 */

header('Content-Type: text/html; charset=UTF-8');

$requiredKey = 'qposclear2026';
$providedKey = isset($_GET['key']) ? (string) $_GET['key'] : '';
if (!hash_equals($requiredKey, $providedKey)) {
    http_response_code(403);
    echo '<!doctype html><html><head><meta charset="utf-8"><title>QPOS installer</title></head><body>';
    echo '<h1>Forbidden</h1><p>Missing or invalid installer key.</p></body></html>';
    exit;
}

@set_time_limit(120);
$root = realpath(__DIR__ . DIRECTORY_SEPARATOR . '..');
$results = array();
$errors = array();
$backupStamp = gmdate('Ymd_His');

function qpos_h($value)
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function qpos_fail($message)
{
    throw new RuntimeException($message);
}

$payloads = array(
    'resources/views/product/index.blade.php' => array('sha1' => 'd5d26d459da56d2187fe7c23cf7a3d5ade3e7a7f', 'data' => ''),
    'resources/views/product/partials/product_list.blade.php' => array('sha1' => 'f2ab63ef0ab084c62321a87f82f31eebe67e52bf', 'data' => ''),
    'resources/views/sell/partials/sell_table_scroll_styles.blade.php' => array('sha1' => '3f1870913f9f9bc6dc95f962b2df6a05536e6c4c', 'data' => ''),
);

try {
    if ($root === false || !is_dir($root) || !is_file($root . '/artisan') || !is_file($root . '/bootstrap/app.php')) {
        qpos_fail('Laravel root was not detected at the parent of the installer directory.');
    }

    foreach ($payloads as $relative => $payload) {
        if (strpos($relative, '..') !== false || substr($relative, 0, 1) === '/') {
            qpos_fail('Unsafe payload path: ' . $relative);
        }

        $decoded = base64_decode($payload['data'], true);
        if ($decoded === false) {
            qpos_fail('Base64 validation failed for ' . $relative);
        }
        if (!hash_equals($payload['sha1'], sha1($decoded))) {
            qpos_fail('SHA1 validation failed for ' . $relative);
        }

        $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        $directory = dirname($target);
        if (!is_dir($directory) || !is_writable($directory)) {
            qpos_fail('Target directory is missing or not writable: ' . $relative);
        }

        $backup = null;
        $mode = 0644;
        if (is_file($target)) {
            $existingMode = @fileperms($target);
            if ($existingMode !== false) {
                $mode = $existingMode & 0777;
            }
            $backup = $target . '.qpos-backup-' . $backupStamp;
            if (!@copy($target, $backup)) {
                qpos_fail('Could not create backup for ' . $relative);
            }
            if (!hash_equals(sha1_file($target), sha1_file($backup))) {
                qpos_fail('Backup verification failed for ' . $relative);
            }
        }

        $temporary = @tempnam($directory, '.qpos-scroll-');
        if ($temporary === false) {
            qpos_fail('Could not create temporary file for ' . $relative);
        }

        $written = @file_put_contents($temporary, $decoded, LOCK_EX);
        if ($written !== strlen($decoded) || !hash_equals($payload['sha1'], sha1_file($temporary))) {
            @unlink($temporary);
            qpos_fail('Temporary write verification failed for ' . $relative);
        }
        @chmod($temporary, $mode);
        if (!@rename($temporary, $target)) {
            @unlink($temporary);
            qpos_fail('Atomic replacement failed for ' . $relative);
        }
        clearstatcache(true, $target);
        if (!is_file($target) || !hash_equals($payload['sha1'], sha1_file($target))) {
            qpos_fail('Installed file verification failed for ' . $relative);
        }

        if (function_exists('opcache_invalidate')) {
            @opcache_invalidate($target, true);
        }
        $results[] = array('path' => $relative, 'backup' => $backup, 'sha1' => $payload['sha1']);
    }

    $compiledDirectory = $root . '/storage/framework/views';
    $clearedViews = 0;
    if (is_dir($compiledDirectory)) {
        $compiledFiles = glob($compiledDirectory . '/*.php');
        if ($compiledFiles !== false) {
            foreach ($compiledFiles as $compiledFile) {
                if (is_file($compiledFile)) {
                    if (@unlink($compiledFile)) {
                        $clearedViews++;
                    } else {
                        $errors[] = 'Could not remove compiled view: ' . basename($compiledFile);
                    }
                }
            }
        }
    } else {
        $errors[] = 'Compiled Blade view directory was not found.';
    }

    if (function_exists('opcache_invalidate')) {
        @opcache_invalidate(__FILE__, true);
    }
    $opcacheReset = function_exists('opcache_reset') ? @opcache_reset() : false;
} catch (Throwable $exception) {
    $errors[] = $exception->getMessage();
}

$success = count($errors) === 0 && count($results) === count($payloads);
http_response_code($success ? 200 : 500);
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>QPOS Product Scroll Installer</title>
<style>body{font:16px/1.5 system-ui,-apple-system,sans-serif;max-width:900px;margin:40px auto;padding:0 20px;color:#172033}h1{color:<?php echo $success ? '#167542' : '#b42318'; ?>}li{margin:.55rem 0}code{word-break:break-all;background:#f2f4f7;padding:2px 5px}.warning{border:2px solid #b42318;background:#fff1f0;padding:16px;margin-top:24px;font-weight:700}</style>
</head>
<body>
<h1><?php echo $success ? 'Product List scroll fix installed' : 'Installation failed'; ?></h1>
<p>Laravel root: <code><?php echo qpos_h($root === false ? '(not found)' : $root); ?></code></p>
<?php if ($results): ?><h2>Installed and verified</h2><ul><?php foreach ($results as $result): ?><li><code><?php echo qpos_h($result['path']); ?></code> — SHA1 <code><?php echo qpos_h($result['sha1']); ?></code><?php if ($result['backup']): ?>; backup <code><?php echo qpos_h($result['backup']); ?></code><?php else: ?>; no previous file to back up<?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (isset($clearedViews)): ?><p>Compiled Blade views removed: <strong><?php echo (int) $clearedViews; ?></strong></p><p>OPcache reset: <strong><?php echo !empty($opcacheReset) ? 'yes' : 'not available or not enabled'; ?></strong></p><?php endif; ?>
<?php if ($errors): ?><h2>Errors</h2><ul><?php foreach ($errors as $error): ?><li><?php echo qpos_h($error); ?></li><?php endforeach; ?></ul><?php endif; ?>
<div class="warning">Security warning: delete <code>qpos_install_product_scroll_like_sales.php</code> from the server immediately, even after a failed run. Then hard-refresh the browser.</div>
</body>
</html>
